--[=[
    @class WuKongServerCsApi
    @server

    本类为悟空框架的服务端管理类.

    主要提供服务端用户门面的相关操作功能.

]=]

local rs = game:GetService("ReplicatedStorage")
require(rs.WuKong.c2l)

local WuKongServerCsApi = {}
local WuKongServerCSharp = _G.wdm.WuKong.RbxServer.WuKongServer
local DebugOptions = require(game.ReplicatedStorage.WuKong.DebugOptions)

local WuKongFacade = require(game.ReplicatedStorage.WuKong.WuKongFacade)

local isReady = false
local functions = nil

-- start server
local templateName = DebugOptions.GetValue("悟空角色模板名称")

functions = WuKongServerCSharp.Start(DebugOptions.IsClientDev, templateName)

local Container = require(game.ReplicatedStorage.WuKong.Types.Container)

type Staff = {}

--[=[
	创建容器
	@param userId number -- 用户编号
	@return Container -- 容器
]=]
function WuKongServerCsApi.CreateWuKongContainer(userId: number): Container.Type
	return functions:CreateWuKongContainer(userId)
end

--[=[
	-- 设置委托, 用来让悟空识别哪些是管理员
]=]
function WuKongServerCsApi.SetAdminCheckingHandler(handler: (userId) -> bool)
	return functions:SetAdminCheckingHandler(handler)
end

--[=[
	序列化悟空容器,得到序列化数据
	@param container Container -- 容器
	@return {} -- 容器序列化后的数据, 方便存储
]=]
function WuKongServerCsApi.SerializeWuKongContainer(container: Container.Type): Staff
	return functions:SerializeWuKongContainer(container)
end

--[=[
	反序列化数据,得到悟空容器
	@param userId number -- 用户编号
	@param staff {} -- 容器序列化后的数据, 方便存储
	@return Container -- 容器
]=]
function WuKongServerCsApi.DeserializeWuKongContainer(userId: number, staff: Staff): Container.Type
	return functions:DeserializeWuKongContainer(userId, staff)
end

--[=[
	注册悟空容器到
	@param container Container -- 容器
]=]
function WuKongServerCsApi.Register(container: Container.Type)
	return functions:Register(container)
end

--[=[
	取消注册悟空容器
]=]
function WuKongServerCsApi.UnRegister(userId: number)
	return functions:UnRegister(userId)
end

--[=[
	重置用户容器到指定模板,如果模板名称为空,则使用"正式"
    调用时, 用户必须已经登陆且注册到了同步中心
 	调用后,请立刻踢出用户,提示其重新登陆.
]=]
function WuKongServerCsApi.ResetUserContainer(userId: number, templateName: string?)
	return functions:ResetUserContainer(userId, templateName)
end

--[=[
	是否注册了悟空容器
]=]
function WuKongServerCsApi.IsRegistered(userId: number): boolean
	return functions:IsRegistered(userId)
end

--[=[
	判断是否含有用户门面
]=]
function WuKongServerCsApi.HasFacade(userId: number): boolean
	return functions:HasFacade(userId)
end

--[=[
    获取用户门面,只有注册到同步中心后，才可以获取到门面
    @return WuKongFacade
]=]
function WuKongServerCsApi.GetFacade(userId: number): WuKongFacade.Type
	return functions:GetFacade(userId)
end

--[=[
    等到用户门面,直到注册到同步中心或者用户离线
    @return WuKongFacade
]=]
function WuKongServerCsApi.WaitFacade(userId: number): WuKongFacade.Type
	local facade
	-- 如果没有获取到门面，等待获取，直到获取到门面或者用户离线
	repeat
		facade = functions:GetFacade(userId)
		if not facade then
			wait()
		end
	until facade or not game.Players:GetPlayerByUserId(userId)
	return facade
end

--[=[
    获取所有用户门面
]=]
function WuKongServerCsApi.GetAllFacades(): { [number]: WuKongFacade.Type }
	return functions:GetAllFacades()
end

return WuKongServerCsApi
